const item = $input.first().json;
const headers = item.headers || {};
const h = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const expected = $env.N8N_MOVFIT_PROXY_TOKEN || 'movfit_proxy_k7x9m2pQ4wR9';
if ((h['x-movfit-proxy'] || '') !== expected) {
  return [{ json: { ok: false, status: 401, error: 'Unauthorized', error_description: 'X-Movfit-Proxy invalido' } }];
}
const raw = item.body ?? item;
const body = typeof raw === 'string' ? (() => { try { return JSON.parse(raw); } catch { return {}; } })() : raw;
const acao = String(body.acao || 'token').toLowerCase();
return [{ json: { ok: true, acao, body } }];

const flatten = (data) => {
  if (data == null) return { error: 'empty_response', error_description: 'Resposta vazia do mcp-auth' };
  if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch { return { error: 'parse_error', error_description: data }; }
  }
  if (data.detail && typeof data.detail === 'object') return { ...data, ...data.detail };
  return data;
};
const { acao, body } = $input.first().json;
const http = this.helpers.httpRequest.bind(this.helpers);
const endpoint = body.token_endpoint || 'https://mcp-auth.conversas.ai/oauth/token';
const enc = (s) => encodeURIComponent(String(s ?? ''));
const formBody = (pairs) => pairs.filter(([, v]) => v != null && v !== '').map(([k, v]) => `${enc(k)}=${enc(v)}`).join('&');
try {
  let pairs;
  if (acao === 'refresh') {
    pairs = [['grant_type', 'refresh_token'], ['refresh_token', body.refresh_token], ['client_id', body.client_id], ['resource', body.resource]];
  } else {
    pairs = [['grant_type', 'authorization_code'], ['code', body.code], ['redirect_uri', body.redirect_uri], ['client_id', body.client_id], ['code_verifier', body.code_verifier], ['resource', body.resource]];
  }
  let data = await http({
    method: 'POST',
    url: endpoint,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    body: formBody(pairs),
    json: true,
    ignoreHttpStatusErrors: true,
  });
  return [{ json: flatten(data) }];
} catch (e) {
  return [{ json: { error: 'n8n_http', error_description: e.message || String(e) } }];
}
